add('air-fryer-beef-joint','Mustard and thyme roast beef',M,8,220,5,50,[[1200,'g','beef roasting joint'],[15,'ml','neutral oil','Source allows 15–30 ml'],[1,'tsp','thyme','','dried'],[1,'tsp','onion granules'],[1,'tsp','mustard powder']],['Rub the joint with oil, thyme, onion and mustard powder. Check the appliance supports 220°C and the joint fits without touching the element.','Air fry at 220°C for 10 minutes. Reduce to 170°C and cook for 30–40 minutes more, checking the centre. Continue until at least 71°C for the medium result used here.','Rest loosely covered on a warm board for 20 minutes, then carve across the grain.'],preheat=3,wait=20,internal=71,nutritionNote='Source estimate for one eighth of a 1.2 kg raw joint, using a 15–30 ml oil range. Listed quantity selects the lower end. Rare source options replaced with NSW medium target.')
add('air-fryer-meatballs','Beef and pork parmesan meatballs',M,25,180,15,12,[[4,'each','pork sausages','Remove casings'],[500,'g','beef mince'],[.5,'each','onion','Very finely diced'],[50,'g','parmesan','Finely grated'],[50,'g','fresh breadcrumbs'],[1,'each','parsley handful','Finely chopped'],[1,'each','egg','Beaten']],['Combine sausagemeat, beef, onion, parmesan, breadcrumbs, parsley and egg. Work together until the mixture holds firmly.','Divide into 25 similar balls, about 3 cm wide, and refrigerate for 20 minutes.','Place in one layer without crowding. Air fry at 180°C for 10–12 minutes, turning halfway. Probe several central meatballs for at least 71°C. Repeat batches as needed.'],preheat=3,wait=20,internal=71,oilFree=True,allergens=['milk','wheat','gluten','egg','sulphites'],portion='One meatball, approximately one twenty-fifth of the batch. Choose multiple portions for a meal.',nutritionNote='Source estimates per meatball from a yield of 20–25. This recipe fixes the yield at 25; individual meatball nutrition remains approximate. Tomato sauce, pasta and bread are excluded.')
add('air-fryer-pork-belly','Crisp roast pork belly',M,6,200,5,60,[[1000,'g','pork belly','Skin-on; source permits 750–1000 g'],[1,'tsp','vegetable oil'],[.5,'tsp','garlic granules']],['Dry the skin thoroughly and score it without cutting into the meat. Rub the oil and garlic over the surface and season with salt and pepper.','Set skin upwards in the basket. Air fry at 200°C for 30 minutes to begin crisping the skin.','Reduce to 180°C and cook 20–30 minutes more, checking the centre reaches 71°C. Rest for 10 minutes before slicing.'],preheat=3,wait=10,internal=71,nutritionNote='Source estimate divides a 750–1000 g pork belly among six portions; the listed recipe uses 1000 g. Fat trimming and skin consumption strongly affect the estimate.')
add('air-fryer-pork-joint','Roast pork shoulder with crackling',M,6,210,5,90,[[1500,'g','boneless pork shoulder','Skin-on; source permits 1000–1500 g'],[7.5,'ml','vegetable oil']],['Pat the pork dry. Score the skin in shallow lines, rub with oil and season with salt. Check basket clearance and that the air fryer supports 210°C.','Air fry at 210°C for 20 minutes. Reduce to 160°C and continue for 60–70 minutes for this 1.5 kg joint.','Check the centre has reached at least 71°C. Rest uncovered for 20 minutes before carving, to help preserve crisp skin.'],wait=20,internal=71,nutritionNote='Source estimate is per one of six portions from a 1–1.5 kg joint; listed recipe uses 1.5 kg. Apple sauce and sides excluded.')
add('air-fryer-turkey-crown','Clementine and herb turkey crown',C,6,180,5,60,[[1700,'g','turkey crown','Bone-in, thawed fully'],[1,'tsp','vegetable oil'],[1,'tsp','mixed herbs','','dried'],[1,'each','clementine','Halved'],[1,'each','shallot','Halved'],[2,'each','garlic cloves','Lightly crushed'],[3,'each','fresh thyme sprigs']],['Confirm the crown fits with safe clearance in your model. Dry it, rub with oil and season with mixed herbs. Place clementine, shallot, garlic and thyme in the cavity or beside it.','Place skin down and air fry at 180°C for 30 minutes. Turn skin upwards and cook another 20–30 minutes.','Probe both thick breast sections without touching bone. Continue until all readings reach 74°C, then rest for 10 minutes before carving.'],preheat=2,wait=10,safety=['Only cook an intact crown if it fits the basket according to the manufacturer clearance requirements.'],nutritionNote='Publisher estimate is for one sixth of a 1.7 kg bone-in crown. Actual edible yield varies. Source 65°C target replaced by NSW 74°C poultry guidance.')
add('air-fryer-sticky-pork-tacos-with-plum-chilli-salsa','Sticky pork tacos with plum salsa',Q,4,190,15,20,[[480,'g','pork belly strips','Cut into 2–3 cm pieces'],[15,'ml','dark brown sugar'],[2,'tsp','ground cumin'],[1,'tsp','chilli powder'],[1,'tsp','ground coriander'],[2,'each','garlic cloves','Grated'],[2,'each','limes','One for pork, one zested and juiced for salsa'],[12,'each','small soft corn tortillas'],[2,'each','plums','Stoned and finely diced'],[10,'g','chives','Sliced'],[10,'g','coriander','Chopped','fresh'],[1,'each','red chilli','Sliced'],[1,'tsp','caster sugar']],['Toss pork with brown sugar, cumin, chilli powder, ground coriander, garlic and one lime’s juice.','Air fry at 190°C in one layer for 15–18 minutes, turning halfway, until the meat is crisp and reaches 71°C.','Mix plums, chives, fresh coriander, chilli, lime zest and juice, and caster sugar to make a salsa. Warm tortillas according to their packet.','Divide pork and salsa between the 12 tortillas; serve three per portion.'],preheat=3,internal=71,oilFree=True,allergens=['wheat','gluten'],nutritionNote='Publisher estimate includes 12 tortillas but also suggests an unmeasured sour-cream garnish. This version omits unmeasured garnish; treat the retained source estimate as approximate rather than recalculated. Check tortilla labels.')
add('charred-harissa-chicken-salad-with-cranberries-apple-herby-yogurt-dressing','Harissa chicken, apple and walnut salad',Q,2,200,10,20,[[1,'tsp','garlic granules'],[1,'tsp','smoked paprika'],[45,'ml','olive oil','15 ml marinade; 30 ml dressing'],[1,'each','lemon','Half for marinade, half for dressing'],[15,'ml','harissa paste'],[4,'each','boneless skinless chicken thighs'],[10,'g','dill','','fresh'],[10,'g','parsley','','fresh'],[45,'ml','Greek yoghurt'],[40,'g','pea shoots'],[40,'g','rocket'],[.5,'each','red apple','Thinly sliced'],[50,'g','feta','Crumbled'],[25,'g','dried cranberries'],[25,'g','walnuts','Chopped']],['Combine garlic, paprika, 15 ml oil, half the lemon juice and harissa. Coat chicken and refrigerate for 20 minutes.','Flatten the thighs in one layer and air fry at 200°C for 16–20 minutes, turning halfway, until 74°C.','Blend dill, parsley, yoghurt, remaining lemon juice and 30 ml oil. Toss half this dressing with the leaves, then add apple, feta, cranberries and walnuts.','Slice the cooked chicken and arrange on the salad. Spoon over the remaining dressing.'],preheat=3,wait=20,internal=74,allergens=['milk','tree-nut','sulphites'],equipment=['Small blender'],nutritionNote='Publisher estimate includes all dressing, feta, cranberries and walnuts. Chicken thigh weights are unspecified; this is a substantial salad rather than a low-calorie plain chicken portion.')
